-- ============================================================
-- System Design Track: Days 1-188
-- Seeds system_design_task column across all 188 challenge days.
-- Thoroughly reviewed and elevated to Senior/Staff engineer interview standards,
-- covering Frontend, Backend, Distributed Systems, Performance, Reliability, and Edge cases.
-- Run after 20260916_rust_challenge_refine.sql.
-- ============================================================

ALTER TABLE rust_challenge_days ADD COLUMN IF NOT EXISTS system_design_task text;
ALTER TABLE rust_challenge_days ADD COLUMN IF NOT EXISTS system_design_completed boolean NOT NULL DEFAULT false;

UPDATE rust_challenge_days SET system_design_task = 'Memory Hierarchy: CPU cache topologies (L1/L2/L3), 64-byte cache lines, spatial/temporal locality. Why pointer-chasing linked structures cause massive TLB/cache misses compared to contiguous arrays.' WHERE day_number = 1;
UPDATE rust_challenge_days SET system_design_task = 'False Sharing & Alignment: Multi-core cache line invalidation (MESI/MOESI protocol) when threads modify adjacent bytes on the same 64-byte line. Hardware padding, #[repr(align(64))], and hardware prefetcher behavior.' WHERE day_number = 2;
UPDATE rust_challenge_days SET system_design_task = 'Virtual Memory & Page Translation: Multi-level page tables, TLB (Translation Lookaside Buffer) hit rates, TLB shootdowns in multi-core systems, and performance impact of 4KB standard pages vs 2MB/1GB Huge Pages.' WHERE day_number = 3;
UPDATE rust_challenge_days SET system_design_task = 'Syscalls vs User Space: Context switch mechanics, kernel privilege boundaries (Ring 0 vs Ring 3), trap handling, CPU register saving, and benchmarking syscall overhead (e.g. gettimeofday vs VDSO).' WHERE day_number = 4;
UPDATE rust_challenge_days SET system_design_task = 'Memory Allocator Architecture: Anatomy of jemalloc / tcmalloc — thread-local caches (tcache/arenas), size classes, slab allocation, and resolving global lock contention in multi-threaded allocators.' WHERE day_number = 5;
UPDATE rust_challenge_days SET system_design_task = 'SIMD & Instruction-Level Parallelism: Vector registers (AVX-512, ARM Neon), superscalar execution, branch prediction, instruction pipelining, and structuring data into Struct-of-Arrays (SoA) for auto-vectorization.' WHERE day_number = 6;
UPDATE rust_challenge_days SET system_design_task = 'Week 1 Review & Architecture Note: Synthesize hardware-software impedance match. Write an architectural brief analyzing how cache layout and memory latency govern low-latency system throughput.' WHERE day_number = 7;
UPDATE rust_challenge_days SET system_design_task = 'Dynamic Allocators Internals: Free list management, First-Fit vs Best-Fit vs Segregated-Fit, and mitigating internal vs external memory fragmentation in long-running services.' WHERE day_number = 8;
UPDATE rust_challenge_days SET system_design_task = 'Buddy Allocator & Coalescing: Binary buddy allocation trees, bitwise address arithmetic for neighbor block identification, and amortized overhead of recursive block merging under high churn.' WHERE day_number = 9;
UPDATE rust_challenge_days SET system_design_task = 'Memory Mapping (mmap): Anonymous memory vs file-backed mappings, page fault handling (major vs minor faults), dirty page flushing (msync/dirty_ratio), and how LMDB/RocksDB leverage OS page cache.' WHERE day_number = 10;
UPDATE rust_challenge_days SET system_design_task = 'Garbage Collection vs Manual Memory: Tracing GC (generational, ZGC/Shenandoah concurrent marking) vs Ref Counting vs RAII/Ownership. Analyzing stop-the-world latency tail spikes (p99.9) in SLA-critical backends.' WHERE day_number = 11;
UPDATE rust_challenge_days SET system_design_task = 'Stack vs Heap Allocation: Compiler escape analysis, stack unwinding, frame pointer omission, cache temporal locality, and memory overhead of short-lived objects.' WHERE day_number = 12;
UPDATE rust_challenge_days SET system_design_task = 'Zero-Copy I/O & Kernel Bypass: Traditional read/write copying through kernel buffers vs sendfile(), splice(), vmsplice(), and DPDK / AF_XDP bypass for line-rate packet processing.' WHERE day_number = 13;
UPDATE rust_challenge_days SET system_design_task = 'Week 2 Review: Compare memory architectures of PostgreSQL (process-per-conn + shared memory), Redis (single-threaded in-memory event loop), and Tokio/Rust (cooperative async worker thread pools).' WHERE day_number = 14;
UPDATE rust_challenge_days SET system_design_task = 'Locking Primitives Deep-Dive: Mutex vs Spinlock vs RwLock vs Seqlock. Cache bouncing during spinlock contention, writer starvation in RwLocks, and reader optimism in Seqlocks.' WHERE day_number = 15;
UPDATE rust_challenge_days SET system_design_task = 'Memory Ordering & Atomics: Hardware memory models (x86 TSO vs ARM weak ordering), compiler reordering fences, and C++11/Rust atomic orderings: Relaxed, Acquire-Release, and Sequentially Consistent.' WHERE day_number = 16;
UPDATE rust_challenge_days SET system_design_task = 'Lock-Free Data Structures & ABA Problem: Compare-And-Swap (CAS) loops, Hazard Pointers, Epoch-Based Reclamation (crossbeam-epoch), and tagged pointers for ABA prevention.' WHERE day_number = 17;
UPDATE rust_challenge_days SET system_design_task = 'Ring Buffers & The Disruptor Pattern: LMAX Disruptor mechanics — circular pre-allocated array, sequence numbers, memory barriers, zero lock contention, and handling multi-million TPS event queues.' WHERE day_number = 18;
UPDATE rust_challenge_days SET system_design_task = 'Thread Models & Runtimes: 1:1 OS threads vs M:N green threads (Go goroutines) vs cooperative async/await event loops (Tokio, Node.js). Stack growth mechanics and context-switching overhead.' WHERE day_number = 19;
UPDATE rust_challenge_days SET system_design_task = 'Deadlock Prevention & Detection: Coffman conditions, strict lock acquisition hierarchies, lock-ordering graph cycle detection, and distributed lock timeouts in transactional databases.' WHERE day_number = 20;
UPDATE rust_challenge_days SET system_design_task = 'Week 3 Review: Design a high-throughput multi-producer multi-consumer (MPMC) lock-free bounded telemetry ring buffer capable of processing 5,000,000 events/sec without allocations.' WHERE day_number = 21;
UPDATE rust_challenge_days SET system_design_task = 'I/O Multiplexing Evolution: Limitations of select() and poll() (O(N) scanning), epoll (Linux) and kqueue (macOS/BSD) red-black tree + ready list (O(1)), Level-Triggered vs Edge-Triggered.' WHERE day_number = 22;
UPDATE rust_challenge_days SET system_design_task = 'io_uring Architecture: Linux asynchronous ring-buffer I/O. Submission Queue (SQ) and Completion Queue (CQ) shared memory, zero-syscall mode (IORING_SETUP_SQPOLL), and registered buffers.' WHERE day_number = 23;
UPDATE rust_challenge_days SET system_design_task = 'TCP Internals & Tuning: 3-way handshake, SYN flood mitigation (SYN cookies), TIME_WAIT socket exhaustion, SO_REUSEPORT, Nagle algorithm (TCP_NODELAY), and BBR vs CUBIC congestion control.' WHERE day_number = 24;
