UPDATE rust_challenge_days SET system_design_task = 'Real-Time Protocols Comparison: WebSocket (full-duplex persistent TCP framing) vs Server-Sent Events (SSE HTTP streaming) vs Long Polling vs WebTransport. Connection state memory overhead.' WHERE day_number = 26;
UPDATE rust_challenge_days SET system_design_task = 'Backpressure & Flow Control: TCP sliding window buffer starvation, reactive streams pull-based backpressure, reactive rate limiting, and shedding load to prevent unbounded memory growth.' WHERE day_number = 27;
