UPDATE rust_challenge_days SET system_design_task = 'RPC Architecture: REST over HTTP/1.1 vs gRPC over HTTP/2. Protobuf binary encoding, multiplexed streaming RPCs, header compression (HPACK), and channel multiplexing.' WHERE day_number = 29;
UPDATE rust_challenge_days SET system_design_task = 'Serialization Protocols & Zero-Copy: Protobuf vs FlatBuffers vs Cap n Proto vs MessagePack vs JSON. Memory layout, in-place traversal without deserialization allocation, and schema evolution.' WHERE day_number = 30;
