UPDATE rust_challenge_days SET system_design_task = 'Distributed Tracing Internals: W3C Trace Context (traceparent, tracestate), span propagation, baggage headers, tail-based sampling vs head-based sampling to control storage costs.' WHERE day_number = 34;
UPDATE rust_challenge_days SET system_design_task = 'Week 5 Review: Design a global Edge API Gateway routing 1,000,000 RPS across 5 upstream microservices with dynamic auth validation and < 3ms p99 proxy overhead.' WHERE day_number = 35;
UPDATE rust_challenge_days SET system_design_task = 'Storage Engines: B+Trees vs Log-Structured Merge-Trees (LSM). In-place updates (PostgreSQL/InnoDB) vs append-only writes (RocksDB/Cassandra). Read/Write/Space amplification trade-offs.' WHERE day_number = 36;
