UPDATE rust_challenge_days SET system_design_task = 'LSM-Tree Internals: MemTable (skip list), Write Stall mechanics, SS-Tables, Bloom filters, and Compaction strategies: Size-Tiered (STCS) vs Leveled Compaction (LCS) vs FIFO.' WHERE day_number = 38;
